"""Alternating paired native A/B. No per-call timer or diagnostic snapshots."""
import json
import os
import platform
import statistics
import subprocess
import uuid
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUTPUT=ROOT/'.deps/ipc-performance-results';OUTPUT.mkdir(exist_ok=True)
rows=[]

def sample(variant,mode,size,count,capacity,iteration):
    directory=ROOT/f'.deps/ipc-perf-{variant}'
    args=[str(uuid.uuid4()),str(count),str(size),mode,str(capacity)]
    host=subprocess.Popen([str(directory/'perf-host64.exe'),*args],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    client=subprocess.Popen([str(directory/'perf-client32.exe'),*args],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    logs=[]
    try:
        for process in (client,host):
            logs.append(process.communicate(timeout=25)[0])
        for process,log in zip((client,host),logs):
            if process.returncode:raise RuntimeError(f'exit={process.returncode} {log}')
        metrics=[json.loads(line) for log in logs for line in log.splitlines() if line.startswith('{')]
        if len(metrics)!=2:raise RuntimeError(f'missing measurements {logs}')
        row={'variant':variant,'mode':mode,'bytes':size,'count':count,'capacity':capacity,'iteration':iteration,'metrics':metrics,'valid':True}
    except (subprocess.TimeoutExpired,RuntimeError) as error:
        row={'variant':variant,'mode':mode,'bytes':size,'count':count,'iteration':iteration,'valid':False,'error':str(error),'logs':logs}
    finally:
        for process in (client,host):
            if process.poll() is None:process.kill();process.wait()
    rows.append(row)
    (OUTPUT/'raw.json').write_text(json.dumps({'machine':platform.platform(),'processor':platform.processor(),'cpu_count':os.cpu_count(),'samples':rows},indent=2))
    print(f'IPC_PERF_SAMPLE {variant} {mode} {size} iteration={iteration} valid={row["valid"]}',flush=True)
    if not row['valid'] and variant=='B':raise RuntimeError(f'New transport native failure: {row}')

scenarios=[('batch',0,24000,8388608),('batch',64,24000,8388608),('batch',1024,12000,8388608),('batch',4096,3000,8388608),('batch',65536,190,8388608),('stream',64,24000,8388608),('wrap',64,12000,4096),('slow',64,12000,4096)]
for mode,size,count,capacity in scenarios:
    # Warm up both variants; preserve raw samples but exclude iteration -1.
    for v in ('A','B'):sample(v,mode,size,count,capacity,-1)
    for iteration in range(11):
        for v in (('A','B') if iteration%2==0 else ('B','A')):sample(v,mode,size,count,capacity,iteration)
summary=[]
for mode,size,_,_ in scenarios:
    group={'mode':mode,'bytes':size,'variants':{}}
    for v in ('A','B'):
        valid=[r for r in rows if r['mode']==mode and r['bytes']==size and r['variant']==v and r['iteration']>=0 and r['valid']]
        failed=[r for r in rows if r['mode']==mode and r['bytes']==size and r['variant']==v and r['iteration']>=0 and not r['valid']]
        stats={'passed':len(valid),'failed':len(failed)}
        for role in ('client','host'):
            for metric in ('wall_ns_call','cpu_ns_call','end_to_end_ns_call'):
                values=[next(m for m in r['metrics'] if m['role']==role)[metric] for r in valid]
                if values:stats[f'{role}_{metric}']={'median':statistics.median(values),'min':min(values),'max':max(values)}
        group['variants'][v]=stats
    summary.append(group)
(OUTPUT/'summary.json').write_text(json.dumps(summary,indent=2))
print('IPC_PERF_SUMMARY '+json.dumps(summary),flush=True)
